 function criticalX(l,a){const L=l.L,w=1.4*(l.udlDead+uniform(l.lines||[],L,'g'))+1.6*(l.udlLive+uniform(l.lines||[],L,'q')),pts=l.points||[],cuts=[...new Set([0,L,...pts.map(x=>x.x)])].sort((a,b)=>a-b);let best={x:0,M:0};const test=x=>{const M=a.left*x-w*x*x/2-pts.reduce((s,p)=>s+(1.4*p.g+1.6*p.q)*Math.max(0,x-p.x),0);if(M>best.M)best={x,M};};for(let i=0;i<cuts.length;i++){test(cuts[i]);if(w>0&&i<cuts.length-1){const x=(a.left-pts.filter(p=>p.x<=cuts[i]+1e-8).reduce((s,p)=>s+1.4*p.g+1.6*p.q,0))/w;if(x>cuts[i]&&x<cuts[i+1])test(x);}}return best.x;}
