 function intro(w,cfg){for(const key of Object.keys(ExcelReportText).filter(k=>k.startsWith('INTRO:'))){const n=+key.split(':')[1];if(n===94){for(const x of ['a) Wind Effects in Hong Kong 2019.','b) Foundations 2017 (2024 Edition).','c) Structural Use of Concrete 2013 (2020 Edition).','d) Dead and Imposed Loads 2011 (2021 Edition).','e) Fire Safety in Buildings 2011.','f) Structural Use of Steel 2011 (2023 Edition).'])w.emit(key,{...baseContext(),x});}else if(n===104){w.add('Slab / beams: fcu = '+fmt(cfg.fcu)+' N/mm²');w.add('Column: fcu = '+fmt(cfg.columnFcu)+' N/mm²');w.add('Transfer beam: fcu = '+fmt(cfg.tbFcu)+' N/mm²');w.emit(key,baseContext());}else if(n===106)w.add('Slab / beam fy = 500 N/mm²; column fy = 500 N/mm².');else w.emit(key,baseContext());}}
 function lines(p,out,section,lo=1,hi=p.total){const w=writer(section),selected=out.rows.filter(r=>r.floor>=lo&&r.floor<=hi&&(section==='A'?out.reportA:out.reportB)?.[r.floor+'|'+r.token]),rank=section==='A'?{SLAB:0,SB:1,MB:2,CB:3,COL:4,TB:5}:{SLAB:0,SB:1,MB:2,CB:2,TB:3,COL:4};if(section==='B')intro(w,out.settings);else aPreface(w,p,out.settings,lo,hi,out.floorScope);const requested=section==='A'?out.reportA:out.reportB,live=new Set(selected.map(r=>r.floor+'|'+r.token));for(const key of Object.keys(requested||{}))if(requested[key]&&+key.split('|')[0]>=lo&&+key.split('|')[0]<=hi&&!live.has(key))w.warning('所选构件已改变，待重新选择：'+key);for(let floor=lo;floor<=hi;floor++){const rows=selected.filter(r=>r.floor===floor).sort((a,b)=>(rank[a.member.displayKind||a.kind]??1)-(rank[b.member.displayKind||b.kind]??1));if(!rows.length)continue;w.add(FloorLevels.name(p,floor)+' · '+rows[0].framing,true);let number=0;for(const r of rows){const checkpoint=w.lines.length;try{if(section==='A'){if(r.kind==='COL')aColumn(w,p,r);else if(r.kind==='TB')aTB(w,p,r);else aSize(w,p,r,++number);}else if(!r.checked||!r.result.values)w.warning(r.id+' · INPUT REQUIRED: '+review(p,r,'B').errors.join('；'));else{if(r.kind==='SLAB')bSlab(w,r,out.settings);else if(r.kind==='COL')bColumn(w,r,out.settings);else if(r.kind==='TB')bTB(w,r,out.settings);else bBeam(w,r,out.settings,out);if(r.result.fail?.length)w.warning(r.id+' · '+r.result.status+': '+r.result.fail.join('；'));}}catch(e){w.lines.splice(checkpoint);w.warning(r.id+' · INPUT REQUIRED: '+e.message);}w.add('');}}if(section==='A')aPostscript(w,p);return w.lines;}
 function content(p,out,section,lo=1,hi=p.total){return '<article class="check-report answer-ruled">'+ReportPaper.rules()+'<div class="answer-paper-content"><h1>Section '+section+' 抄</h1>'+lines(p,out,section,lo,hi).map(x=>x.image?'<figure class="copy-figure"><img src="'+x.image+'" alt="'+esc(x.text)+'"><figcaption>'+esc(x.text)+'</figcaption></figure>':x.table?aTableHTML(x):'<p class="'+(x.warning?'report-warning':x.heading?'copy-heading':'copy-line')+(x.template?' copy-template':'')+'"'+(x.support?' data-support=\"'+esc(x.support)+'\"':'')+(x.key?' data-excel-source="'+esc(x.key)+'"':'')+'>'+esc(x.text).replace(/____|XXXX|x{3,4}|\[missing\]/g,'<mark class=\"copy-required\">$&</mark>').replace(/\n/g,'<br>')+'</p>').join('')+(section==='A'&&typeof OverallReport!=='undefined'?OverallReport.sectionA(p):'')+'</div></article>';}
