 function document(p,o,section,lo,hi){return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Section '+section+' 抄 · '+esc(p.name)+'</title><style>'+css+ReportPaper.css+'</style><body><button onclick="window.print()">A4 打印 / PDF</button>'+content(p,o,section,lo,hi)+'<script>'+ReportPaper.script()+'</scr'+'ipt></body></html>';}
 function text(html){return html.replace(/<\/(?:td|th)>/gi,'\t').replace(/<\/tr>/gi,'\n').replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/(p|h\d|figcaption)>/g,'\n').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");}
 return {errorSummary,content,document,text,css,lines,sizing,supportLimits,review,parseColumnAreas,columnA,beamBinding};
