if(typeof module!=='undefined')module.exports=Reports;

// Form state only; colour is never used to decide engineering completeness.
const InputColours=(()=>{
 const legend='<div class="input-colour-key"><span class="input-key-required">黄色：需输入</span><span class="input-key-default">浅蓝：默认值，可修改</span></div>';
 const val=(tag,k)=>tag.match(new RegExp('\\b'+k+'="([^"]*)"'))?.[1]??'';
 function selectValue(s){const options=[...s.matchAll(/<option\b([^>]*)>([\s\S]*?)<\/option>/g)],x=options.find(m=>/\bselected\b/.test(m[1]))||options[0];return x?(val(x[1],'value')||x[2]):'';}
 function decorate(html,p){const cfg=Loading.defaults,sv=id=>selectValue(html.match(new RegExp('<select\\b[^>]*id="'+id+'"[^>]*>[\\s\\S]*?<\\/select>'))?.[0]||''),usage=sv('lg-usage')||sv('ex-range-usage'),live=UsageOptions.find(x=>x.name===usage)?.ll,mode=sv('ex-mode')||'auto';
  const paint=(tag,body='',close='')=>{const id=val(tag,'id'),field=val(tag,'data-f'),action=val(tag,'data-action'),type=val(tag,'type'),value=close==='</select>'?selectValue(tag+body+close):close==='</textarea>'?body:val(tag,'value');let state='';if(['checkbox','range','file','hidden'].includes(type)||/\b(?:disabled|readonly)\b/.test(tag))return tag+body+close;
   if(action==='group'&&['headroom','em'].includes(field)&&value==='')state='required';else if(action==='default')state='default';
   else if(Object.hasOwn(cfg,id.replace(/^ex-/,''))&&Number(value)===cfg[id.slice(3)])state='default';
   else if(/^(lg|ex-range)-(lo|hi|scope)$/.test(id))state='default';
   else if(/^(lg|ex-range)-(dl|usage)$/.test(id)&&!value)state='required';
   else if(/^(lg|ex-range)-sdl$/.test(id))state=value===''?'required':Number(value)===0?'default':'';
   else if(/^(lg|ex-range)-ll$/.test(id))state=value===''?'required':live!==undefined&&Number(value)===live?'default':'';
   else if(id.startsWith('ex-inline-')&&/-(area|extra)$/.test(id)&&!value)state='required';else if(id.startsWith('ex-inline-')&&id.endsWith('-sw')&&!value)state='default';else if(id==='ex-a-column-areas')state='';else if(id==='ex-a-area-value'&&!value)state='required';else if(id==='ex-area-extra-dead'&&!value)state='required';else if(id==='ex-area-slab-sw'&&!value)state='default';
   else if(id==='ex-cs-edge'&&!['left','right','top','bottom'].includes(value))state='required';
   else if(id==='ex-slab-type'&&value==='SLAB')state='default';
   else if(['ex-supportA','ex-supportZ'].includes(id))state=body.includes('原 Support 已失效')?'required':value==='auto'?'default':'';
   else if(id==='ex-cover'&&!value)state='default';
   else if(['ex-dead','ex-live','ex-udlDead','ex-udlLive'].includes(id))state=mode==='manual'&&!value?'required':'';
   else if(['ex-extraDead','ex-torsion'].includes(id)&&Number(value)===0)state='default';
   else if(['ex-mode','ex-steel-mode','ex-system','ex-a-support','ex-fixedEnd'].includes(id)&&['auto','AUTO','Braced','跟随构件'].includes(value))state='default';
   else if(id==='ex-factor'&&!value)state='default';
   else if(action&&['x','y','x1','x2','y1','y2','b','d','length','spacing'].includes(field)&&value==='')state=field==='d'?'default':'required';
   if(!state)return tag+body+close;const note=state==='required'?'需输入':'默认值，可修改';return tag.replace(/>$/,' data-input-state="'+state+'" data-input-note="'+note+'">')+body+close;
  };
  let out=html.replace(/<select\b[^>]*>[\s\S]*?<\/select>|<textarea\b[^>]*>[\s\S]*?<\/textarea>|<input\b[^>]*>/g,s=>{const m=s.match(/^(<[^>]+>)([\s\S]*)(<\/(?:select|textarea)>)$/);return m?paint(m[1],m[2],m[3]):paint(s);});
  return /data-input-state=/.test(out)?legend+out:out;
 }
 function refreshElement(e,p){if(!e?.outerHTML||!e.setAttribute)return;const encode=v=>String(v??'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');let tag=e.outerHTML.replace(/ data-input-(?:state|note)="[^"]*"/g,'');if(e.tagName==='SELECT')tag=tag.replace(/>[\s\S]*<\/select>$/, '><option selected value="'+encode(e.value)+'">'+encode(e.value)+'</option></select>');else if(e.tagName==='TEXTAREA')tag=tag.replace(/>[\s\S]*<\/textarea>$/,'>'+encode(e.value)+'</textarea>');else tag=tag.replace(/\bvalue="[^"]*"/,'value="'+encode(e.value)+'"');let context='';for(const id of ['lg-usage','ex-range-usage','ex-mode']){const s=document.getElementById(id);if(s&&s!==e)context+='<select id="'+id+'"><option selected value="'+encode(s.value)+'">'+encode(s.value)+'</option></select>';}
  const marked=(decorate(tag+context,p).match(/<(?:input|select|textarea)\b[^>]*>/)?.[0]||'').match(/data-input-state="([^"]+)"/),state=marked?.[1];if(state){e.setAttribute('data-input-state',state);e.setAttribute('data-input-note',state==='required'?'需输入':'默认值，可修改');}else{e.removeAttribute('data-input-state');e.removeAttribute('data-input-note');}}
 function bind(getProject){for(const name of ['input','change'])document.addEventListener(name,event=>{const e=event.target;if(!['INPUT','SELECT','TEXTAREA'].includes(e?.tagName))return;refreshElement(e,getProject());if(/^(lg|ex-range)-usage$/.test(e.id))requestAnimationFrame(()=>refreshElement(document.getElementById(e.id.replace(/usage$/,'ll')),getProject()));});}
 return {decorate,refreshElement,bind};
})();
